set -eu; W=/home/storage/781/4477781/user/webapp; DB=$W/openwebui-data/webui.db; "$W/envs/openwebui/bin/python" - "$DB" <<'PY'
import json,sqlite3,sys
db=sys.argv[1]
c=sqlite3.connect("file:"+db+"?mode=ro",uri=True)
c.execute("PRAGMA query_only=ON")
sensitive=("secret","token","password","credential","api_key","apikey","authorization","cookie")
terms=("ollama","task.model","task_model","context","keep_alive","num_ctx","timeout","base_url","model")
def safe_scalar(v):
    return isinstance(v,(str,int,float,bool)) or v is None
def walk(v,path=""):
    if isinstance(v,dict):
        for k,x in sorted(v.items(),key=lambda kv:str(kv[0])):
            p=(path+"."+str(k)).strip(".")
            low=p.lower()
            if any(s in low for s in sensitive):
                continue
            if safe_scalar(x):
                if any(t in low for t in terms):
                    print("CFG",p,"=",json.dumps(x,ensure_ascii=False))
            elif isinstance(x,list) and len(x)<=40 and all(safe_scalar(y) for y in x):
                if any(t in low for t in terms):
                    print("CFG",p,"=",json.dumps(x,ensure_ascii=False))
            else:
                walk(x,p)
    elif isinstance(v,list):
        for i,x in enumerate(v[:40]):
            walk(x,f"{path}[{i}]")
print("--- config keys ---")
for (k,) in c.execute('select "key" from config order by "key"'):
    print(k)
print("--- relevant config scalars (secret fields excluded) ---")
for k,val in c.execute('select "key", value from config order by "key"'):
    try: obj=json.loads(val) if isinstance(val,str) else val
    except Exception: continue
    walk(obj,str(k))
print("--- model bindings and runtime params ---")
wanted={"num_ctx","keep_alive","num_predict","think","temperature","top_p","top_k","repeat_penalty","seed","max_tokens","mirostat","stop"}
for rid,base,name,active,params in c.execute('select id,base_model_id,name,is_active,params from model order by name,id'):
    print("MODEL",json.dumps({"id":rid,"base_model_id":base,"name":name,"is_active":bool(active)},ensure_ascii=False,sort_keys=True))
    try: p=json.loads(params) if params else {}
    except Exception: p={}
    if isinstance(p,dict):
        out={k:v for k,v in p.items() if k in wanted and safe_scalar(v)}
        if out: print("PARAMS",json.dumps(out,ensure_ascii=False,sort_keys=True))
c.close()
